package com.lbos.commercecustomer.entity; import jakarta.persistence.*;import java.util.*;import java.time.*;import java.math.*; @Entity @Table(name="customer_cart",uniqueConstraints= @UniqueConstraint(name="uq_cart_customer_product",columnNames={"customer_profile_id","product_id"})) public class CustomerCart {@Id @GeneratedValue(strategy=GenerationType.UUID) @Column(name="cart_id") private UUID id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="customer_profile_id") private CustomerProfile customer; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="product_id") private Product product; @Column(name="added_at",nullable=false) private OffsetDateTime addedAt; @PrePersist void add(){addedAt=OffsetDateTime.now();} public CustomerCart(){} public UUID getId(){return id;} public void setId(UUID v){id=v;} public CustomerProfile getCustomer(){return customer;} public void setCustomer(CustomerProfile v){customer=v;} public Product getProduct(){return product;} public void setProduct(Product v){product=v;} public OffsetDateTime getAddedAt(){return addedAt;}}